with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , BENNAME as BENEFICIARY_NAME
        , 'BJAZ_HM_HOSPITAL_MASTER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master') }}
    where (nullif(trim(HOSID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BENEFICIARY_NAME end) as BENEFICIARY_NAME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when BENEFICIARY_NAME is not null
                     then md5(upper(coalesce(cast(BENEFICIARY_NAME as varchar), '')))
                end as SAT_PROVIDER_BANKING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PROVIDER_BANKING_HASHDIFF is not null
